sys_script_include.script:
var MSS_Collateral_Utils = Class.create();
MSS_Collateral_Utils.prototype = {
    initialize: function() {},
    //MSSCOLATERAL-82: Create Widget Inbound Record for payload.......
    insertInboundWidgetRecord: function(requestData, payload) {
        try {
            var eventsArray = [];
            var grWidget = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
            grWidget.initialize();
            grWidget.object_id = requestData.objectid;
            grWidget.object_version = requestData.objectversion;
            grWidget.object_type = requestData.objecttype;
            grWidget.object_id_type = requestData.objectidtype;
            grWidget.event_status = requestData.eventstatus;
            grWidget.setValue('event_date_time', requestData.eventdatetime.replace('T', ' '));
            grWidget.source = requestData.source;
            grWidget.message_id = requestData.messageid;
            grWidget.event_type = requestData.eventtype;
            grWidget.additional_attributes = requestData.additionalattributes;
            grWidget.payload = JSON.stringify(payload);
            var widInbound = grWidget.insert();
        } catch (e) {
             gs.error('Script Include - MSS_Collateral_Utils:- Unknown exception while processing Widget Inbound Request ' + e.message);
        //    this.errorLogAndXmatterAlert("ERROR", "Unknown exception while processing Widget Inbound Request: insertInboundWidgetRecord" + e.message); //MSSCOLATRL-479
        }
    },

    //MSSCOLATRL - 83: Logic to create a record in Case Table
    insertCollateralCase: function(inboundSysID) {
        try {
            var grInbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
            grInbound.addQuery('sys_id', inboundSysID);
            grInbound.query();
            if (grInbound.next()) {
                var grCollateralCase = new GlideRecord('x_hsb11_mss_coll_0_collateral_case_table');

                // Parse Additional Attribute Data
                var additionalattr = {};
                try {
                    additionalattr = JSON.parse(grInbound.additional_attributes + '');
                } catch (e) {
                     gs.info('Script Include - MSS_Collateral_Utils:- Failed to parse additional_attributes: ' + e.message);
                 //   this.errorLogAndXmatterAlert("ERROR", "Failed to parse additional_attributes: insertCollateralCase" + e.message); //MSSCOLATRL-479
                }

                // Parse Payload Data
                var payload = {};
                try {
                    payload = JSON.parse(grInbound.payload + '');
                } catch (e) {
                     gs.info('Script Include - MSS_Collateral_Utils:- Failed to parse payload: ' + e.message);
                  //  this.errorLogAndXmatterAlert("ERROR", "Failed to parse payload: insertCollateralCase" + e.message);  //MSSCOLATRL-479
                }

                // Calling function to check for Duplicate Movement ID and Type
                var movID = grInbound.object_id || '';
                var movType = additionalattr.flow ? additionalattr.flow : '';
                var manloc = payload.managingLocationName ? payload.managingLocationName : '';

                var uniqueMovementID = this.checkDuplicateMovementID(movID, movType, manloc);
                if (uniqueMovementID == true) {
                    //gs.info("inside if statement check for uniqueMovementID");
                    grCollateralCase.initialize();

                    // Parse Header Data
                    grCollateralCase.u_message_id = grInbound.message_id || '';
                    grCollateralCase.u_source = grInbound.source || '';
                    grCollateralCase.u_event_type = grInbound.event_type || '';
                    grCollateralCase.event_status = grInbound.event_status || '';
                    grCollateralCase.event_date_time = grInbound.event_date_time || '';
                    grCollateralCase.u_object_type = grInbound.object_type || '';
                    grCollateralCase.movement_origin = grInbound.object_id_type || '';
                    grCollateralCase.movement_id = grInbound.object_id || '';
                    grCollateralCase.u_objectversion = grInbound.object_version || '';
                    grCollateralCase.state = 1;

                    grCollateralCase.instrument_class = additionalattr.instrumentClass ? additionalattr.instrumentClass : '';
                    grCollateralCase.settlement_date = additionalattr.settlementDate ? new GlideDateTime(additionalattr.settlementDate.replace('T', ' ')).getDisplayValue() : '';
                    grCollateralCase.direction = additionalattr.postDirection ? additionalattr.postDirection : '';
                    grCollateralCase.stp_status = additionalattr.state ? additionalattr.state : '';
                    grCollateralCase.movement_type = additionalattr.flow ? additionalattr.flow : '';
                    grCollateralCase.agreement_id = additionalattr.agreementId ? additionalattr.agreementId : '';
                    grCollateralCase.agreement_name = additionalattr.agreementName ? additionalattr.agreementName : '';

                    // // Parse Payload Data
                    // var payload = {};
                    // try {
                    //     payload = JSON.parse(grInbound.payload + '');
                    // } catch (e) {
                    //     gs.info('Script Include - MSS_Collateral_Utils:- Failed to parse payload: ' + e.message);
                    // }
                    grCollateralCase.managing_location = payload.managingLocationName ? payload.managingLocationName : '';
                    grCollateralCase.client_type_indicator = payload.clientIndicator ? payload.clientIndicator : '';
                    grCollateralCase.hpn_type = payload.HPNType ? payload.HPNType : '';
                    grCollateralCase.currency_cutoff_time = payload.ccyCutoffTime ? payload.ccyCutoffTime : '';
                    grCollateralCase.time_zone = payload.timeZone ? payload.timeZone : '';
                    //grCollateralCase.u_3rd_triparty = payload.tripartyCustodian ? payload.tripartyCustodian.toString() : '';
                    grCollateralCase.u_3rd_triparty = (payload.tripartyCustodian == false) ? 'false' : (payload.tripartyCustodian == null || payload.tripartyCustodian.toString().toLowerCase() == "undefined") ? '' : payload.tripartyCustodian.toString();
                    grCollateralCase.custodian_name = payload.tripartyCustodianName ? payload.tripartyCustodianName : '';
                    //grCollateralCase.asm_enable = payload.mtu ? payload.mtu.toString() : '';
                    grCollateralCase.asm_enable = (payload.mtu == false) ? 'false' : (payload.mtu == null || payload.mtu.toString().toLowerCase() == "undefined") ? '' : payload.mtu.toString();
                    grCollateralCase.currency = payload.ccy ? payload.ccy : '';
                    grCollateralCase.instrument_id = payload.issuedId ? payload.issuedId : '';
                    grCollateralCase.triparty_instrument_id = payload.issuedIdOverride ? payload.issuedIdOverride : '';
                    grCollateralCase.position_type = payload.affectedPosition ? payload.affectedPosition : '';
                    grCollateralCase.notional = payload.notional ? payload.notional : '';
                    grCollateralCase.margin_type = payload.collateralMarginType ? payload.collateralMarginType : '';
                    grCollateralCase.stp_details = payload.stateInfo ? payload.stateInfo : '';
                    grCollateralCase.csa_type = payload.agreementType ? payload.agreementType : '';
                    grCollateralCase.product_field = payload.direction ? payload.direction : '';
                    grCollateralCase.activity_sub_type = payload.activitySubType ? payload.activitySubType : '';
                    grCollateralCase.group_member_code = payload.groupMember ? payload.groupMember : '';
                    grCollateralCase.branch_number = payload.branchNumber ? payload.branchNumber : '';
                    grCollateralCase.payment_type = payload.paymentType ? payload.paymentType : '';

                    // Additional Fields that are required at Task Creation
                    grCollateralCase.activity = payload.activity ? payload.activity : '';
                    //grCollateralCase.agreement_id = payload.agreementId ? payload.agreementId : '';
                    grCollateralCase.agreement_type = payload.agreementTypeName ? payload.agreementTypeName : '';
                    grCollateralCase.business_line = payload.businessLine ? payload.businessLine : '';
                    grCollateralCase.counterpary_legal_name = payload.counterpartyName ? payload.counterpartyName : '';
                    grCollateralCase.created_by = payload.createdBy ? payload.createdBy : '';
                    grCollateralCase.created_timestamp = payload.createdTimestamp ? payload.createdTimestamp : '';
                    // grCollateralCase.miss_cutoff = payload.cutOffTimeExceeded ? payload.cutOffTimeExceeded.toString() : '';
                    grCollateralCase.miss_cutoff = (payload.cutOffTimeExceeded == false) ? 'false' : (payload.cutOffTimeExceeded == null || payload.cutOffTimeExceeded.toString().toLowerCase() == "undefined") ? '' : payload.cutOffTimeExceeded.toString();
                    grCollateralCase.instrument_type = payload.instrumentTypeName ? payload.instrumentTypeName : '';
                    grCollateralCase.place_of_settlement = payload.placeOfSettlement ? payload.placeOfSettlement : '';
                    grCollateralCase.position = payload.position ? payload.position : '';
                    grCollateralCase.settlement_system = payload.settlementSystem ? payload.settlementSystem : '';
                    grCollateralCase.trade_date = payload.tradeDate ? payload.tradeDate : '';

                    //Logic to derive the STP Acronym, STP Enable and Dealing Position Account field values
                    grCollateralCase.stp_acronym = (additionalattr.instrumentClass == 'Cash') ? payload.stpCashAcronym : payload.externalId;

                    grCollateralCase.dealing_position_account = ((payload.accountNumber == 'NULL') || (payload.accountNumber == '') || (payload.accountNumber == 'N/A') || (payload.accountNumber == 'undefined')) ? payload.accountNumber : payload.account;

                    var origination = grInbound.object_id_type;
                    if ((origination == 'Distribution') || (origination == 'WashTOB') || (origination == 'RollIn') || (origination == 'WashEOP')) {
                        // grCollateralCase.stp_enable = payload.stpInterest ? payload.stpInterest.toString() : '';
                        grCollateralCase.stp_enable = (payload.stpInterest == false) ? 'false' : (payload.stpInterest == null || payload.stpInterest.toString().toLowerCase() == "undefined") ? '' : payload.stpInterest.toString();
                    } else if (additionalattr.instrumentClass == 'Cash') {
                        // grCollateralCase.stp_enable = payload.stpCash ? payload.stpCash.toString() : '';
                        grCollateralCase.stp_enable = (payload.stpCash == false) ? 'false' : (payload.stpCash == null || payload.stpCash.toString().toLowerCase() == "undefined") ? '' : payload.stpCash.toString();
                    } else {
                        //  grCollateralCase.stp_enable = payload.stpBonds ? payload.stpBonds.toString() : '';
                        grCollateralCase.stp_enable = (payload.stpBonds == false) ? 'false' : (payload.stpBonds == null || payload.stpBonds.toString().toLowerCase() == "undefined") ? '' : payload.stpBonds.toString();
                    }

                    // Assignment Team
                    //grCollateralCase.u_assignment_team = this.getAssignmentTeam(origination.toString()); //--> Commented in MVP2 where the Assignment Team value would be evaluated on the Task Level and not the Case. The Assignment Team value would then be copied to the Case.

                    //Creating a JSON object for holding the payload data and passing the object as an argument to 
                    /*var naIndicatorsObj = {
                        agreementTypeName: payload.agreementTypeName ? payload.agreementTypeName.toString().toLowerCase() : '',
                        clientIndicator: payload.clientIndicator ? payload.clientIndicator.toString().toLowerCase() : '',
                        managingLocationName: payload.managingLocationName ? payload.managingLocationName.toString().toLowerCase() : '',
                        instrumentClass: additionalattr.instrumentClass ? additionalattr.instrumentClass.toString().toLowerCase() : '',
                        stateInfo: payload.stateInfo ? payload.stateInfo.toString().toLowerCase() : '',
                        origin: grInbound.object_id_type ? grInbound.object_id_type.toString().toLowerCase() : '',
                        tripartyCustodian: payload.tripartyCustodian ? payload.tripartyCustodian.toString().toLowerCase() : '',
                        postDirection: additionalattr.postDirection ? additionalattr.postDirection.toString().toLowerCase() : '',
                        instrumentTypeName: payload.instrumentTypeName ? payload.instrumentTypeName.toString().toLowerCase() : '',
                    };


                    var wn = this.getCommentsForNAItems(naIndicatorsObj);

                    if (wn != "Actionable Exception") {
                        grCollateralCase.work_notes = wn;
                        grCollateralCase.state = '3';
                    }*/ //--> Commented in MVP2 where the outcome rules would be evaluated on the Task Level and not on the Case level.

                    // Insert Record on Case Table
                    grCollateralCase.insert();

                }
                //Updating the status of the Widget Inbound Record based on whether the Case is Unique or Duplicate
                if (uniqueMovementID == true) {
                    grInbound.status = 'Processed';
                } else if (uniqueMovementID == false) {
                    grInbound.status = 'Duplicate Exception';
                } else if (uniqueMovementID == "block hbus otc") {
                    grInbound.status = 'Exception creation blocked for HBUS OTC managing location';
                }
                grInbound.update();
            }
        } catch (e) {
             gs.info('Script Include - MSS_Collateral_Utils:- Unknown exception while creating case from widget inbound record ' + e.message);
         //   this.errorLogAndXmatterAlert("ERROR", "Unknown exception while creating case from widget inbound record: insertCollateralCase" + e.message);  //MSSCOLATRL-479
            grInbound.status = 'Error';
            grInbound.update();
        }

    },

    //MSSCOLATRL - 87: Logic to fetch the Assignment team value
    /*getAssignmentTeam: function(origination_value) {
        try {
            var ori = origination_value.toLowerCase();
            // Can we use system properties
            if (ori == "distribution" || ori == "rollin" || ori == "washeop" || ori == "washtob") {
                return "collateral_interest";
            } else if (ori == "manual" || ori == "margincall" || ori == "profitandloss" || ori == "substitution") {
                return "collateral_margin";
            } else {
                return "collateral_margin";
            }
        } catch (e) {
            gs.info('Script Include - MSS_Collateral_Utils:- Unknown exception while updating the Assignment Team value ' + e.message);
        }
    },*/ //--> Commented in MVP2 where the Assignment Team value would be evaluated on the Task Level and not the Case. The Assignment Team value would then be copied to the Case.

    //MSSCOLATRL - 88: Logic to decide whether the case is Actionable or Non-actionable
    /*getCommentsForNAItems: function(naIndicatorsObj) {
        try {
            //gs.info(naIndicatorsObj.origin + " " + naIndicatorsObj.tripartyCustodian + " " + naIndicatorsObj.postDirection + " " + naIndicatorsObj.instrumentTypeName);
            if (naIndicatorsObj.agreementTypeName == "swapagent vm iosco") {

                return "No action required - SwapAgent excluded from STP";

            } else if ((naIndicatorsObj.clientIndicator == "hse") && (naIndicatorsObj.managingLocationName == "hbeu otc" || naIndicatorsObj.managingLocationName == "hbeu otc cash" || naIndicatorsObj.managingLocationName == "hbeu repo") && (naIndicatorsObj.instrumentClass == "cash")) {

                return "No action required - CCP excluded from STP";

            } else if ((naIndicatorsObj.stateInfo == "payment direction is receive, but there is no mt101 receive customerssi.") && (naIndicatorsObj.managingLocationName == "hbfr paris otc" || naIndicatorsObj.managingLocationName == "hbfr paris repo") && (naIndicatorsObj.instrumentClass == "cash")) {

                return "No action required - move not STP";

            } else if ((naIndicatorsObj.origin == "distribution" || naIndicatorsObj.origin == "washtob" || naIndicatorsObj.origin == "rollin" || naIndicatorsObj.origin == "waseop") && (naIndicatorsObj.tripartyCustodian == "true") && (naIndicatorsObj.postDirection == "delivtoprin") && (naIndicatorsObj.instrumentTypeName == "triparty order")) {

                return "No action required - Collateral held away at custodian";

            } else {

                return "Actionable Exception";

            }
        } catch (e) {
            gs.info('Script Include - MSS_Collateral_Utils:- Unknown exception while identifying whether the case is Actionable or Non-actionable ' + e.message);
        }
    },*/ //--> Commented in MVP2 where the outcome rules would be evaluated on the Task Level and not on the Case level.

    //MSSCOLATRL - 111: Logic for Duplicate Movement ID: identification & processing
    checkDuplicateMovementID: function(movid, movtype, manloc) {
        try {
            var movementid = movid.toLowerCase();
            var movementtype = movtype.toLowerCase();
            var manlocation = manloc.toLowerCase();

            //Checking if the exception exists on the Collateral Case Table
            var grColCase = new GlideRecord('x_hsb11_mss_coll_0_collateral_case_table'); //Gliding on the Collateral Case Table
            grColCase.addQuery('movement_id', movementid); //Checking if there is already a ase record with the same Movement ID
            grColCase.query();
            while (grColCase.next()) {
                /*If logic to check whether any of the below combinations are true and restricting the creation of the case record:
                1. For Existing and New Record the 'Movement Type=New'
                2. For Existing and New Record the 'Movement Type=Cancel'
                3. For Existing Record 'Movement Type=Cancel' and New Record 'Movement Type=New'*/
                if ((grColCase.movement_type.toLowerCase() == "new" && movementtype == "new") || ((grColCase.movement_type.toLowerCase() == "cancel") && (movementtype == "new" || movementtype == "cancel"))) {
                    return false;
                }
            }

            //Checking if the exception exists on the Collateral Closed Case Table
            var grColClosedCase = new GlideRecord('x_hsb11_mss_coll_0_collateral_closed_case_table'); //Gliding on the Collateral Closed Case Table
            grColClosedCase.addQuery('movement_id', movementid); //Checking if there is already a ase record with the same Movement ID
            grColClosedCase.query();
            while (grColClosedCase.next()) {
                /*If logic to check whether any of the below combinations are true and restricting the creation of the case record:
                1. For Existing and New Record the 'Movement Type=New'
                2. For Existing and New Record the 'Movement Type=Cancel'
                3. For Existing Record 'Movement Type=Cancel' and New Record 'Movement Type=New'*/
                if ((grColClosedCase.movement_type.toLowerCase() == "new" && movementtype == "new") || ((grColClosedCase.movement_type.toLowerCase() == "cancel") && (movementtype == "new" || movementtype == "cancel"))) {
                    return false;
                }
            }

            //MSSCOLATRL-248: Blocking the exception creation if the toggle is disabled for HBUS Exceptions.
            if (manlocation == "hbus otc" && gs.getProperty('x_hsb11_mss_coll_0.Toggle for HBUS Exceptions') == "false") {
                return "block hbus otc";
            }

            return true;
        } catch (e) {
             gs.info('Script Include - MSS_Collateral_Utils:- Unknown exception while identification and processing of the Duplicate Movement IDs ' + e.message);
        //    this.errorLogAndXmatterAlert("ERROR", "Unknown exception while identification and processing of the Duplicate Movement IDs: checkDuplicateMovementID" + e.message);  //MSSCOLATRL-479
        }
    },

    //MSSCOLATRL - 127 : Update Task Details Function called from the Flow Designer "HSBC_Collateral_Case_Task_Creation_Flow"
    updateTaskDetails: function(colsysid) {
        var flag = false;
        try {
            // Fetch Task Record by sys_id
            var grColTask = new GlideRecord('x_hsb11_mss_coll_0_collateral_task_table');
            if (grColTask.get(colsysid)) {
                // Get sys_id of corresponding Case Record from reference field
                var caseSysId = grColTask.collateral_case_id.toString();
                var grCase = new GlideRecord('x_hsb11_mss_coll_0_collateral_case_table');
                if (grCase.get(caseSysId)) {

                    // List of fields to copy from Case to Task
                    var fieldsToCopy = [
                        // Header Data
                        'u_message_id', 'u_source', 'u_event_type', 'event_status', 'event_date_time', 'u_object_type',
                        'movement_origin', 'movement_id', 'u_objectversion', 'state',

                        // Additional Attributes
                        'instrument_class', 'settlement_date', 'direction', 'stp_status', 'movement_type', 'agreement_name',
                        // Payload Data

                        'managing_location', 'client_type_indicator', 'hpn_type', 'currency_cutoff_time', 'time_zone',
                        'u_3rd_triparty', 'custodian_name', 'asm_enable', 'currency', 'instrument_id', 'triparty_instrument_id',
                        'position_type', 'notional', 'margin_type', 'stp_details', 'csa_type', 'product_field', 'activity_sub_type', 'group_member_code', 'branch_number', 'payment_type',
                        // Additional Fields

                        'activity', 'agreement_id', 'agreement_type', 'business_line', 'counterpary_legal_name', 'created_by',
                        'created_timestamp', 'miss_cutoff', 'instrument_type', 'place_of_settlement', 'position',
                        'settlement_system', 'trade_date',
                        // Conditional Fields

                        'stp_acronym', 'dealing_position_account', 'stp_enable', //'u_assignment_team ',--> this has been commented as the assignment team value shall come to task table first and will then be copied to the case table.
                    ];

                    // Copy fields from Case to Task
                    fieldsToCopy.forEach(function(field) {
                        if (grCase.isValidField(field) && grColTask.isValidField(field)) {
                            grColTask[field] = grCase[field];
                        }
                    });

                    //Creating a JSON object for holding the payload data and passing it to the function to fetch the Rule Category and Assignment Team values.
                    var conditionIndicators = {
                        agreementTypeName: grCase.agreement_type ? grCase.agreement_type.toString().toLowerCase() : '',
                        clientIndicator: grCase.client_type_indicator ? grCase.client_type_indicator.toString().toLowerCase() : '',
                        managingLocationName: grCase.managing_location ? grCase.managing_location.toString().toLowerCase() : '',
                        instrumentClass: grCase.instrument_class ? grCase.instrument_class.toString().toLowerCase() : '',
                        stateInfo: grCase.stp_details ? grCase.stp_details.toString().toLowerCase() : '',
                        origin: grCase.movement_origin ? grCase.movement_origin.toString().toLowerCase() : '',
                        tripartyCustodian: grCase.u_3rd_triparty ? grCase.u_3rd_triparty.toString().toLowerCase() : '',
                        postDirection: grCase.direction ? grCase.direction.toString().toLowerCase() : '',
                        instrumentTypeName: grCase.instrument_type ? grCase.instrument_type.toString().toLowerCase() : '',
                        mtu: grCase.asm_enable ? grCase.asm_enable.toString().toLowerCase() : '',
                    };

                    //Fetching and storing the Rule category and Assignment Team values returned from the 'getRuleCategoryAndAssignmentTeam' function
                    var fetchedRuleValue = this.getRuleCategoryAndAssignmentTeam(conditionIndicators);
                    grColTask.rule_category = fetchedRuleValue.category.toString();
                    grColTask.u_assignment_team = fetchedRuleValue.team.toString();
                    //gs.info("datatype rule: "+typeof grColTask.rule_category);
                    //gs.info("datatype AT: "+typeof grColTask.u_assignment_team);
                    var adminSysID = gs.getProperty('x_hsb11_mss_coll_0.System Administrator SysID'); //Sys ID for the System Admin User.

                    //Identifying the non-actionable excpetions to update the outcome, assigned to and state values.
                    if (grColTask.rule_category == '1' || grColTask.rule_category == '2' || grColTask.rule_category == '2a' || grColTask.rule_category == '3' || grColTask.rule_category == '4' || grColTask.rule_category == '4a') {
                        grColTask.u_outcome = "No Action required - Auto Close";
                        grColTask.assigned_to = adminSysID;
                        grColTask.state = 3;

                        var nonActionableComments = "";

                        //gs.info("Rule Category: "+ grColTask.rule_category);
                        //gs.info("datatype: "+typeof grColTask.rule_category);

                        //Updating the comments on the closed exception as per the calculated rule category value.
                        switch (grColTask.rule_category.toString()) {
                            case '1':
                                nonActionableComments = "No action required - SwapAgent excluded from STP";
                                //gs.info("Entered 1");
                                break;

                            case '2':
                                nonActionableComments = "No action required - CCP excluded from STP";
                                break;

                            case '2a':
                                nonActionableComments = "No action required - CCP excluded from STP";
                                break;

                            case '3':
                                nonActionableComments = "No action required - move not STP";
                                break;

                            case '4':
                                nonActionableComments = "No action required - Collateral help away at custodian";
                                break;

                            case '4a':
                                nonActionableComments = "No action required - Separate process";
                                break;
                        }
                        //gs.info("Nonactionable Comments: "+ nonActionableComments);
                        var grTaskJournalEntry = new global.UpdateComments();
                        grTaskJournalEntry.updateCollateralTaskComments(grColTask.sys_id, nonActionableComments);


                    }

                    // Update Task Record
                    grColTask.update();
                    flag = true;
                }
            }
            return flag;
        } catch (e) {
             gs.info('Script Include - MSS_Collateral_Utils:- updateTaskDetails error: ' + e.message);
          //  this.errorLogAndXmatterAlert("ERROR", "updateTaskDetails error: updateTaskDetails" + e.message);  //MSSCOLATRL-479
            return false;
        }
    },

    //MSSCOLATRL-177: Function to derive the Rule Category and Assignment Team values to identify the outcomes against each rule
    getRuleCategoryAndAssignmentTeam: function(conditionIndicators) {
        try {
            var output = {};
            var arrUtil = new global.ArrayUtil(); //Creating the ArrayUtil() class object

            //Converting the string property into an Array 
            var manLocHBEU = gs.getProperty('x_hsb11_mss_coll_0.Managing Locations HBEU').split(',');
            var manLocHBAP = gs.getProperty('x_hsb11_mss_coll_0.Managing Locations HBAP').split(',');

            //Condition check for calculating the Rule category and the Assignment Team values.
            if (conditionIndicators.agreementTypeName == "swapagent vm iosco") {
                output.team = 'collateral_margin';
                output.category = '1';
            } else if (conditionIndicators.clientIndicator == "hse" && arrUtil.contains(manLocHBEU, conditionIndicators.managingLocationName) && conditionIndicators.instrumentClass == "cash") {
                output.team = 'collateral_margin';
                output.category = '2';
            } else if (conditionIndicators.clientIndicator == "hse" && arrUtil.contains(manLocHBAP, conditionIndicators.managingLocationName) && conditionIndicators.instrumentClass == "debt") {
                output.team = 'collateral_margin';
                output.category = '2a';
            } else if ((conditionIndicators.stateInfo == "payment direction is receive, but there is no mt101 receive customerssi." && (conditionIndicators.managingLocationName == "hbfr paris otc" || conditionIndicators.managingLocationName == "hbfr paris repo") && conditionIndicators.instrumentClass == "cash")) {
                output.team = 'collateral_margin';
                output.category = '3';
            } else if ((conditionIndicators.origin != "distribution" && conditionIndicators.origin != "washtob" && conditionIndicators.origin != "rollin" && conditionIndicators.origin != "washeop") && conditionIndicators.tripartyCustodian == "true" && conditionIndicators.postDirection == "delivtoprin" && conditionIndicators.instrumentTypeName != "triparty order") {
                output.team = 'collateral_margin';
                output.category = '4';
            } else if (conditionIndicators.instrumentClass == "debt" && conditionIndicators.managingLocationName == "hbus otc") {
                output.team = 'collateral_margin';
                output.category = '4a';
            } else if ((conditionIndicators.origin == "distribution" || conditionIndicators.origin == "washtob" || conditionIndicators.origin == "rollin" || conditionIndicators.origin == "washeop") && (conditionIndicators.managingLocationName != "hbfr paris otc" && conditionIndicators.managingLocationName != "hbfr paris repo") && conditionIndicators.instrumentClass == "cash" && conditionIndicators.stateInfo == "cannot proceed because cutoff time has been exceeded.") {
                output.team = 'collateral_interest';
                output.category = '5';
            } else if ((conditionIndicators.origin == "distribution" || conditionIndicators.origin == "washtob" || conditionIndicators.origin == "rollin" || conditionIndicators.origin == "washeop") && (conditionIndicators.managingLocationName != "hbfr paris otc" && conditionIndicators.managingLocationName != "hbfr paris repo") && conditionIndicators.instrumentClass == "cash" && conditionIndicators.stateInfo != "cannot proceed because cutoff time has been exceeded.") {
                output.team = 'collateral_interest';
                output.category = '6';
            } else if ((conditionIndicators.origin == "distribution" || conditionIndicators.origin == "washtob" || conditionIndicators.origin == "rollin" || conditionIndicators.origin == "washeop") && (conditionIndicators.managingLocationName == "hbfr paris otc" || conditionIndicators.managingLocationName == "hbfr paris repo")) {
                output.team = 'collateral_interest';
                output.category = '7';
            } else if (conditionIndicators.tripartyCustodian == "true" && conditionIndicators.postDirection == "rtntocpty" && conditionIndicators.instrumentTypeName != "triparty order" && conditionIndicators.mtu == "true") {
                output.team = 'collateral_margin';
                output.category = '8';
            } else if (conditionIndicators.tripartyCustodian == "true" && conditionIndicators.postDirection == "rtntocpty" && conditionIndicators.instrumentTypeName != "triparty order" && conditionIndicators.mtu == "false") {
                output.team = 'collateral_margin';
                output.category = '9';
            } else {
                if (conditionIndicators.origin == "distribution" || conditionIndicators.origin == "washtob" || conditionIndicators.origin == "rollin" || conditionIndicators.origin == "washeop") {
                    output.team = 'collateral_interest';
                    output.category = '10_interest'; //this is to control the outcome values for interest. we can change this if not required.
                } else {
                    output.team = 'collateral_margin';
                    output.category = '10_margin'; //this is to control the outcome values for margin. we can change this if not required.
                }
            }
            //var returnedOutput = JSON.stringify(output);
            return output;

        } catch (e) {
             gs.info('Script Include - MSS_Collateral_Utils:- Unknown exception while fetching the Rule category and Assignment Team ' + e.message);
          //  this.errorLogAndXmatterAlert("ERROR", "Unknown exception while fetching the rule category and Assignment Team: " + e.message);  //MSSCOLATRL-479
        }
    },

    // MSSCOLATRL-185: Function to categorize the Exception cases as Settmoves
    setSettmovesFlag: function(taskId, taskType) {
        try {
            // Query the Collateral Task Table using the taskId
            var eCase = new GlideRecord('x_hsb11_mss_coll_0_collateral_task_table');
            eCase.addQuery('sys_id', taskId);
            eCase.query();

            if (eCase.next()) {
                // MSSCOLATRL-185: Check settmoves cases closed by the current user
                // and set 'settmoves_latest_closed_record' to false for other records
                if (taskType != "TREATS API Task") {
                    var eSettmovesCase = new GlideRecord('x_hsb11_mss_coll_0_collateral_closed_task_table');
                    eSettmovesCase.addQuery('settmoves', true);
                    eSettmovesCase.addQuery('settmoves_latest_closed_record', true);
                    eSettmovesCase.addQuery('closed_by', gs.getUserID());
                    eSettmovesCase.query();

                    while (eSettmovesCase.next()) {
                        eSettmovesCase.setValue('settmoves_latest_closed_record', false);
                        eSettmovesCase.update();
                    }
                    eCase.setValue('settmoves_latest_closed_record', true);
                }

                // Always set the 'settmoves' flag to true for the current record
                //MSSCOLATRL- 506
                eCase.setValue('settmoves', true);
                eCase.update();
            }

        } catch (e) {
             gs.error('Script Include - MSS_Collateral_Utils: Unknown exception while setting the settmoves and settmoves_latest_closed_record flag. Error: ' + e.message);  //MSSCOLATRL-479
            // this.errorLogAndXmatterAlert("ERROR", "Unknown exception while setting the settmoves and settmoves_latest_closed_record flag. Error:  setSettmovesFlag" + e.message);
        }
    },


    // MSSCOLATRL-218: Function to set the New Settlement Date on the Collateral Case Record
    setNewSettlementDate: function(caseId, newDate) {
        try {
            var eCase = new GlideRecord('x_hsb11_mss_coll_0_collateral_case_table');
            eCase.addQuery('sys_id', caseId);
            eCase.query();
            if (eCase.next()) {
                eCase.new_settlement_date = newDate;
                eCase.update();
            }
        } catch (e) {
             gs.error('Script Include - MSS_Collateral_Utils:- Unknown exception while setting the new settlement date on the collateral case exception ' + e.message);  //MSSCOLATRL-479
            // this.errorLogAndXmatterAlert("ERROR", "Unknown exception while setting the new settlement date on the collateral case exception: setNewSettlementDate" + e.message);
        }
    },
    copyMakerToChecker: function(checkerSysId) {
        try {
            var tableName = 'x_hsb11_mss_coll_0_collateral_task_table';

            var checkerGr = new GlideRecord(tableName);
            if (!checkerGr.get(checkerSysId)) {
                gs.error('copyMakerToChecker - Checker task not found: ' + checkerSysId);
                return false;
            }

            var caseId = checkerGr.getValue('collateral_case_id');
            if (!caseId) {
                gs.error('copyMakerToChecker - collateral_case_id is empty on checker task: ' + checkerSysId);
                return false;
            }

            var makerGr = new GlideRecord(tableName);
            makerGr.addQuery('collateral_case_id', caseId);
            makerGr.addQuery('collateral_task_type', 'Base Task');
            makerGr.orderByDesc('sys_created_on');
            makerGr.setLimit(1);
            makerGr.query();

            if (!makerGr.next()) {
                gs.error('copyMakerToChecker - Base Task not found for case: ' + caseId + ' (checker=' + checkerSysId + ')');
                return false;
            }

            var fieldsToCopy = [
                'u_message_id', 'u_source', 'u_event_type', 'event_status', 'event_date_time', 'u_object_type',
                'movement_origin', 'movement_id', 'u_objectversion',

                'instrument_class', 'settlement_date', 'direction', 'stp_status', 'movement_type', 'agreement_name',

                'managing_location', 'client_type_indicator', 'hpn_type', 'currency_cutoff_time', 'time_zone',
                'u_3rd_triparty', 'custodian_name', 'asm_enable', 'currency', 'instrument_id', 'triparty_instrument_id',
                'position_type', 'notional', 'margin_type', 'stp_details', 'csa_type', 'product_field', 'activity_sub_type',

                'activity', 'agreement_id', 'agreement_type', 'business_line', 'counterpary_legal_name', 'created_by',
                'created_timestamp', 'miss_cutoff', 'instrument_type', 'place_of_settlement', 'position',
                'settlement_system', 'trade_date',

                'stp_acronym', 'dealing_position_account', 'stp_enable', 'u_assignment_team', 'rule_category', 'u_outcome', 'new_settlement_date'
            ];

            for (var i = 0; i < fieldsToCopy.length; i++) {
                var f = fieldsToCopy[i];
                if (makerGr.isValidField(f) && checkerGr.isValidField(f)) {
                    checkerGr.setValue(f, makerGr.getValue(f));
                }
            }

            checkerGr.update();
            return true;

        } catch (e) {
             gs.error('copyMakerToChecker - Exception: ' + e.message);
			// this.errorLogAndXmatterAlert("ERROR", "copyMakerToChecker - Exception: copyMakerToChecker" + e.message);
            return false;
        }
    },
	//MSSCOLATRL-479 added xMatterAlert
    xMatterAlert(severity, txt) {
        try {
            new x_hsb11_mss_coll_0.MSS_Collateral_XMatter_ITID_WidgetFailureHandler().createITIDEvent("WARNING", txt, 'MSS-OT-IQUBE-SERVICENOW-COLLATERAL');
        } catch (errorInfo) {
            gs.error('[iQube - Collateral]: MSS_Collateral_Utils.xMatterAlert | Unknown exception while processing' + errorInfo.message);
        }
    },

